<?php defined('ABSPATH') || exit; $status = $order->get_status(); $customer = trim($order->get_formatted_billing_full_name()); $billing = $order->get_formatted_billing_address(); $shipping = $order->get_formatted_shipping_address(); $shippingItems = $order->get_items('shipping'); ?>
<header class="fa-admin-welcome fa-oc-header"><div><p><a class="fa-oc-back" href="<?php echo esc_url($page->url()); ?>">← بازگشت به سفارش‌ها</a></p><h1 tabindex="-1">سفارش #<?php echo esc_html($order->get_order_number()); ?></h1><p><?php echo esc_html($order->get_date_created() ? wc_format_datetime($order->get_date_created(), 'Y/m/d H:i') : '—'); ?></p></div><span class="fa-oc-status <?php echo esc_attr($page->statusClass($status)); ?>"><?php echo esc_html($page->statusLabel($status)); ?></span></header>
<?php if ($message = $page->queryString('fa_oc_success')) : ?><div class="notice notice-success"><p><?php echo esc_html($message); ?></p></div><?php endif; ?><?php if ($message = $page->queryString('fa_oc_error')) : ?><div class="notice notice-error"><p><?php echo esc_html($message); ?></p></div><?php endif; ?>
<section class="fa-oc-single-grid"><div class="fa-oc-main-column">
<article class="fa-oc-panel"><header class="fa-oc-panel-header"><h2>محصولات سفارش</h2></header><div class="fa-oc-items"><?php foreach ($order->get_items('line_item') as $item) : $product = $item->get_product(); $qty = max(1, (int)$item->get_quantity()); ?><div class="fa-oc-item"><div class="fa-oc-item-thumb"><?php echo $product ? wp_kses_post($product->get_image(['64','64'], ['class'=>'fa-oc-item-image'])) : '<span class="dashicons dashicons-products" aria-hidden="true"></span>'; ?></div><div class="fa-oc-item-info"><strong><?php echo esc_html($item->get_name()); ?></strong><small>SKU: <?php echo esc_html($product && $product->get_sku() ? $product->get_sku() : '—'); ?></small></div><div class="fa-oc-item-meta"><span>قیمت واحد</span><strong><?php echo wp_kses_post($page->money((float)$item->get_total() / $qty, $order->get_currency())); ?></strong></div><div class="fa-oc-item-meta"><span>تعداد</span><strong>× <?php echo esc_html((string)$qty); ?></strong></div><div class="fa-oc-item-meta"><span>تخفیف</span><strong><?php echo wp_kses_post($page->money((float)$item->get_subtotal()-(float)$item->get_total(), $order->get_currency())); ?></strong></div><div class="fa-oc-item-meta"><span>مبلغ</span><strong><?php echo wp_kses_post($page->money((float)$item->get_total(), $order->get_currency())); ?></strong></div></div><?php endforeach; ?></div></article>
<article class="fa-oc-panel"><header class="fa-oc-panel-header"><h2>خلاصه مالی</h2></header><dl class="fa-oc-financial-list"><?php foreach (['جمع محصولات'=>$order->get_subtotal(),'تخفیف'=>$order->get_discount_total(),'ارسال'=>$order->get_shipping_total(),'مالیات'=>$order->get_total_tax(),'مرجوعی'=>$order->get_total_refunded(),'مبلغ نهایی'=>$order->get_total()] as $label=>$amount) : ?><div class="<?php echo $label === 'مبلغ نهایی' ? 'fa-oc-financial-total' : ''; ?>"><dt><?php echo esc_html($label); ?></dt><dd><?php echo wp_kses_post($page->money((float)$amount, $order->get_currency())); ?></dd></div><?php endforeach; ?></dl></article>
<article class="fa-oc-panel"><header class="fa-oc-panel-header"><h2>یادداشت‌های داخلی</h2></header><div class="fa-oc-notes"><?php if ($notes === []) : ?><p class="fa-oc-muted">یادداشت داخلی ثبت نشده است.</p><?php endif; ?><?php foreach ($notes as $note) : ?><div class="fa-oc-note"><p><?php echo esc_html($note->content); ?></p><small><?php echo esc_html($note->added_by ?: 'مدیر'); ?> · <?php echo esc_html($note->date_created ? wc_format_datetime($note->date_created, 'Y/m/d H:i') : ''); ?></small></div><?php endforeach; ?></div><form class="fa-oc-note-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="fa_order_center_add_note"><input type="hidden" name="order_id" value="<?php echo esc_attr((string)$order->get_id()); ?>"><?php wp_nonce_field('fa_order_center_note_' . $order->get_id()); ?><label for="fa-oc-note">یادداشت جدید</label><textarea id="fa-oc-note" name="order_note" rows="4" maxlength="2000" required></textarea><button type="submit" class="button button-primary">ثبت یادداشت</button></form></article>
<article class="fa-oc-panel fa-oc-extension"><header class="fa-oc-panel-header"><h2>اطلاعات تکمیلی</h2></header><?php do_action('fandoogh_order_center_extension_area', $order); ?></article></div>
<aside class="fa-oc-side-column"><article class="fa-oc-panel"><header class="fa-oc-panel-header"><h2>مدیریت وضعیت</h2></header><form class="fa-oc-status-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="fa_order_center_update_status"><input type="hidden" name="order_id" value="<?php echo esc_attr((string)$order->get_id()); ?>"><?php wp_nonce_field('fa_order_center_status_' . $order->get_id()); ?><label for="fa-oc-order-status">وضعیت سفارش</label><select id="fa-oc-order-status" name="order_status"><?php foreach ($page->statuses() as $key=>$label) : $value=$page->normalizeStatus((string)$key); ?><option value="<?php echo esc_attr($value); ?>" <?php selected($status,$value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select><button type="submit" class="button button-primary">ذخیره وضعیت</button></form></article>
<article class="fa-oc-panel"><header class="fa-oc-panel-header"><h2>مشتری</h2></header><dl class="fa-oc-data-list"><div><dt>نام</dt><dd><?php echo esc_html($customer ?: 'مهمان'); ?></dd></div><div><dt>ایمیل</dt><dd dir="ltr"><?php echo esc_html($order->get_billing_email() ?: '—'); ?></dd></div><div><dt>تلفن</dt><dd dir="ltr"><?php echo esc_html($order->get_billing_phone() ?: '—'); ?></dd></div></dl></article>
<article class="fa-oc-panel"><header class="fa-oc-panel-header"><h2>آدرس صورتحساب</h2></header><div class="fa-oc-address"><?php echo $billing ? wp_kses_post($billing) : '<span class="fa-oc-muted">ثبت نشده است.</span>'; ?></div></article><article class="fa-oc-panel"><header class="fa-oc-panel-header"><h2>آدرس ارسال</h2></header><div class="fa-oc-address"><?php echo $shipping ? wp_kses_post($shipping) : '<span class="fa-oc-muted">ثبت نشده است.</span>'; ?></div></article>
<article class="fa-oc-panel"><header class="fa-oc-panel-header"><h2>پرداخت و ارسال</h2></header><dl class="fa-oc-data-list"><div><dt>روش پرداخت</dt><dd><?php echo esc_html($order->get_payment_method_title() ?: '—'); ?></dd></div><div><dt>شناسه تراکنش</dt><dd dir="ltr"><?php echo esc_html($order->get_transaction_id() ?: '—'); ?></dd></div><div><dt>روش ارسال</dt><dd><?php echo esc_html(implode('، ', array_map(static fn($item): string => (string)$item->get_name(), $shippingItems)) ?: '—'); ?></dd></div><div><dt>هزینه ارسال</dt><dd><?php echo wp_kses_post($page->money((float)$order->get_shipping_total(), $order->get_currency())); ?></dd></div><?php if ($tracking !== []) : ?><div><dt>رهگیری</dt><dd><?php foreach ($tracking as $track) : ?><span class="fa-oc-tracking"><?php echo esc_html($track['provider'] ? $track['provider'] . ': ' : ''); ?><?php if ($track['url']) : ?><a href="<?php echo esc_url($track['url']); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html($track['number']); ?></a><?php else : ?><?php echo esc_html($track['number']); ?><?php endif; ?></span><?php endforeach; ?></dd></div><?php endif; ?></dl></article>
<?php if ($meta !== []) : ?><article class="fa-oc-panel"><header class="fa-oc-panel-header"><h2>اطلاعات تکمیلی سفارش</h2></header><dl class="fa-oc-data-list"><?php foreach ($meta as $item) : ?><div><dt><?php echo esc_html($item['key']); ?></dt><dd><?php echo esc_html($item['value']); ?></dd></div><?php endforeach; ?></dl></article><?php endif; ?></aside></section>
